// Types and sample data for the test system

export interface Question {
  id: string;
  text: string;
  options: string[];
  correctIndex: number;
  topic: string;
  difficulty: "easy" | "medium" | "hard";
  explanation: string;
  concept: string;
  detailedExplanation?: string;
  relatedQuestions?: string[];
}

export interface TestConfig {
  subject: string;
  topic: string;
  difficulty: "easy" | "medium" | "hard";
  questionCount: number;
}

export interface AnswerRecord {
  questionId: string;
  selectedIndex: number | null;
  timeSpent: number;
  isCorrect: boolean;
}

export interface TestResult {
  config: TestConfig;
  questions: Question[];
  answers: AnswerRecord[];
  totalTime: number;
  completedAt: Date;
}

export const subjects = [
  { id: "physics", name: "Physics", icon: "⚡" },
  { id: "chemistry", name: "Chemistry", icon: "🧪" },
  { id: "mathematics", name: "Mathematics", icon: "📐" },
  { id: "biology", name: "Biology", icon: "🧬" },
];

export const topicsBySubject: Record<string, string[]> = {
  physics: ["Kinematics", "Thermodynamics", "Optics", "Electromagnetism", "Waves"],
  chemistry: ["Organic Chemistry", "Inorganic Chemistry", "Physical Chemistry", "Electrochemistry"],
  mathematics: ["Calculus", "Algebra", "Trigonometry", "Probability", "Geometry"],
  biology: ["Cell Biology", "Genetics", "Ecology", "Human Physiology", "Evolution"],
};

export function generateQuestions(config: TestConfig): Question[] {
  const pool = questionPool[config.subject]?.[config.topic] || fallbackQuestions(config);
  const filtered = pool.filter(q => q.difficulty === config.difficulty || pool.length <= config.questionCount);
  const source = filtered.length >= config.questionCount ? filtered : pool;
  const shuffled = [...source].sort(() => Math.random() - 0.5);
  return shuffled.slice(0, Math.min(config.questionCount, shuffled.length));
}

function fallbackQuestions(config: TestConfig): Question[] {
  return Array.from({ length: config.questionCount }, (_, i) => ({
    id: `q-${i}`,
    text: `Sample ${config.topic} question ${i + 1}: What is the fundamental principle behind ${config.topic.toLowerCase()}?`,
    options: [
      "Conservation of energy applies",
      "Newton's third law governs it",
      "Entropy always increases",
      "Wave-particle duality explains it",
    ],
    correctIndex: 0,
    topic: config.topic,
    difficulty: config.difficulty,
    explanation: `This is based on the fundamental principles of ${config.topic}.`,
    concept: config.topic,
    detailedExplanation: `Understanding ${config.topic} requires grasping the foundational laws that govern it. The correct answer relates to the most universally applicable principle.`,
    relatedQuestions: [
      `What are the basic laws governing ${config.topic}?`,
      `How does conservation apply in ${config.topic}?`,
    ],
  }));
}

